type Worker struct {
	mu    sync.Mutex
	stats map[string]int
	done  bool
}

func NewWorker() *Worker {
	return &Worker{stats: make(map[string]int)}
}

func (w *Worker) Run(jobs <-chan Job) {
	for !w.done {
		job := <-jobs
		w.mu.Lock()
		w.stats[job.Kind]++
		w.mu.Unlock()
		process(job)
	}
}

func (w *Worker) Stop() {
	w.done = true
}

func (w *Worker) Snapshot() map[string]int {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.stats
}
